\par\nopagebreak
\begin{minipage}[t]{0.62\linewidth}\vspace{0pt}
\textbf{1. Định nghĩa \& Tính chất} [[br]] - \textbf{Định nghĩa}: Hình vuông là tứ giác có bốn góc vuông và bốn cạnh bằng nhau. [[br]] - \textbf{Tính chất}: Hình vuông có tất cả tính chất của hình chữ nhật và hình thoi: [[br]] \hspace*{1.4em}+ Bốn cạnh bằng nhau ($AB=BC=CD=DA$). [[br]] \hspace*{1.4em}+ Bốn góc bằng nhau và bằng $90^\circ$. [[br]] \hspace*{1.4em}+ Hai đường chéo \textbf{bằng nhau}, \textbf{vuông góc} với nhau tại trung điểm của mỗi đường và là các \textbf{đường phân giác} của các góc ở đỉnh ($AC = BD$, $AC \perp BD$, $OA=OB=OC=OD$).
\end{minipage}\hfill
\begin{minipage}[t]{0.33\linewidth}\vspace{0pt}
\centering
